#!/usr/bin/env bash
# Generate SOURCES.md from components.tsv (#67). One machine-made table of every component the
# kit can download, each with its license, the link to that license, and its upstream source —
# so the list can never disagree with the data file CI already guards (check-components.sh).
#   build-sources.sh            regenerate SOURCES.md from components.tsv
#   build-sources.sh --check    regenerate into a temp file and fail if SOURCES.md differs (CI)
# Comparison ignores CR/LF so a Windows checkout passes the same as Linux.
set -eu
cd "$(dirname "$0")/../.." || exit 1
TSV="components.tsv"
OUT="SOURCES.md"
check=0; [ "${1:-}" = "--check" ] && check=1

gen() {
  cat <<'HEAD'
<!-- GENERATED by .github/scripts/build-sources.sh from components.tsv — do not edit by hand.
     Change components.tsv, then run: bash .github/scripts/build-sources.sh -->
# Sources

Every component this kit can download, with its license, the link to that license, and its
upstream source. This table is generated from [`components.tsv`](components.tsv) — the single
data file CI checks, so nothing here can be added without a license. For the narrative notes,
restriction markers and the per-PDF breakdown, see [DATA-SOURCES.md](DATA-SOURCES.md).

| Component | Part | License | Source |
|---|---|---|---|
HEAD
  awk -F'\t' '
    /^#/ || $0 ~ /^[ \t]*$/ { next }
    $1=="component" { next }
    { printf "| %s | `%s` | [%s](%s) | <%s> |\n", $1, $2, $3, $4, $5 }
  ' "$TSV"
}

if [ "$check" = 1 ]; then
  tmp="$(mktemp)"; trap 'rm -f "$tmp"' EXIT
  gen > "$tmp"
  if [ ! -f "$OUT" ] || ! diff -q <(sed 's/\r$//' "$tmp") <(sed 's/\r$//' "$OUT") >/dev/null; then
    echo "FAIL: $OUT is out of date with components.tsv. Run: bash .github/scripts/build-sources.sh"
    exit 1
  fi
  echo "OK: $OUT matches components.tsv."
else
  gen > "$OUT"
  echo "Wrote $OUT ($(($(grep -c '^| ' "$OUT") - 1)) components)."
fi
